const fs=require('fs'),assert=require('assert/strict');const R=require('node:path').resolve(__dirname,'../../..');const {avecJeu,page}=require(R+'/outils/bancs/mobile-navigateur.cjs');const {parse}=require(R+'/outils/audits/audit-i18n-global.cjs');const source=fs.readFileSync(R+'/plateau-core.js','utf8'),node=parse(source).body.find(n=>n.type==='FunctionDeclaration'&&n.id.name==='showToast');const langs=['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'];
(async()=>avecJeu(async(browser,o)=>{const p=await page(browser,o,320,900,false,{texteMinimum:true});await p.addScriptTag({content:`var state={pa:50,arg:100,currentCity:'capitale',country:'republic'};var calls=0;window.RP_I18N_GAME_ENABLED=true;window.noterIncidentSession=()=>{};window.sbRpc=async(fn)=>{calls++;return fn==='universite_mon_etat'?{ok:true,cursus_disponibles:[]}:fn==='universite_prochaine_etape'?{ok:true,etape:null}:{ok:true};};`});for(const f of ['i18n/i18next.min.js','i18n/resources.js','i18n/plateau-bridge.js','i18n/toast-resources.js','i18n/toast-bodies-resources.js','i18n/plateau-init.js'])await p.addScriptTag({url:o+'/'+f});await p.addScriptTag({content:source.slice(node.start,node.end)});await p.addScriptTag({url:o+'/plateau-universite.js'});await p.waitForFunction(()=>!!window.RPUniversityI18n);for(const first of langs){await p.evaluate(l=>i18next.changeLanguage(l),first);await p.evaluate(()=>universiteDiplomer());const calls=await p.evaluate(()=>window.calls);for(const next of langs){await p.evaluate(l=>i18next.changeLanguage(l),next);const r=await p.evaluate(()=>({t:document.getElementById('toast-result').textContent,b:document.getElementById('toast-sub').textContent,expected:RPUniversityI18n.words[RPPlateauI18n.language()],calls:window.calls}));assert.equal(r.t,r.expected.titre);assert.equal(r.b,r.expected.diplome);assert.equal(r.calls,calls);}}console.log('showToast réel et catalogues communs : 81 bascules, textes corrects, aucun rejeu RPC.');await p.close();}))().catch(e=>{console.error(e);process.exitCode=1;});
